INSERT INTO public.rocks (name, type, description, composition, texture, color, formation_process, hardness, grain_size, uses, locations) VALUES
('Granite', 'igneous', 'A coarse-grained intrusive igneous rock composed mainly of quartz, feldspar, and mica. It forms from slow crystallization of magma beneath the Earth''s surface.', 'Quartz, Feldspar, Mica', 'Coarse-grained, crystalline', 'Pink, gray, white', 'Formed by slow cooling of magma deep within the Earth''s crust', 6.5, 'Coarse (visible crystals)', 'Construction, monuments, countertops', ARRAY['Worldwide', 'India - Karnataka, Tamil Nadu']),
('Basalt', 'igneous', 'A fine-grained volcanic rock that forms from rapidly cooling lava. It is the most common rock in the Earth''s crust.', 'Pyroxene, Plagioclase feldspar', 'Fine-grained, may contain vesicles', 'Dark gray to black', 'Formed by rapid cooling of lava at or near the Earth''s surface', 6.0, 'Fine (microscopic crystals)', 'Road base, concrete aggregate, sculptures', ARRAY['Deccan Plateau - India', 'Hawaii, Iceland']),
('Sandstone', 'sedimentary', 'A clastic sedimentary rock composed mainly of sand-sized mineral particles, most commonly quartz.', 'Quartz, Feldspar, Rock fragments', 'Granular, varies from fine to coarse', 'Tan, yellow, red, white', 'Formed by cementation of sand particles deposited by water, wind, or ice', 6.0, 'Medium (sand-sized)', 'Building stone, paving, glass manufacturing', ARRAY['Rajasthan - India', 'Worldwide']),
('Limestone', 'sedimentary', 'A sedimentary rock composed primarily of calcium carbonate, often containing fossil remains.', 'Calcium carbonate (calcite)', 'Fine to coarse-grained, sometimes crystalline', 'White, gray, cream, yellow', 'Formed from accumulated shells and skeletons of marine organisms', 3.0, 'Fine to medium', 'Cement production, building stone, soil conditioner', ARRAY['Madhya Pradesh - India', 'Worldwide']),
('Marble', 'metamorphic', 'A metamorphic rock formed from limestone subjected to heat and pressure, resulting in recrystallization.', 'Calcite, Dolomite', 'Medium to coarse-grained, crystalline', 'White, gray, pink, black (often veined)', 'Formed by metamorphism of limestone or dolostone', 3.0, 'Medium to coarse', 'Sculptures, building decoration, monuments', ARRAY['Rajasthan - India', 'Carrara - Italy', 'Greece']),
('Gneiss', 'metamorphic', 'A high-grade metamorphic rock with distinct banding due to segregation of different mineral types.', 'Quartz, Feldspar, Mica, Amphibole', 'Coarse-grained with distinct banding', 'Gray, pink, white, black bands', 'Formed by high-grade regional metamorphism', 7.0, 'Coarse', 'Building stone, monuments, decorative purposes', ARRAY['Southern India', 'Scandinavia', 'Canada']);
INSERT INTO public.minerals (name, chemical_formula, description, luster, hardness, color, streak, cleavage, fracture, crystal_system, specific_gravity, uses, locations) VALUES
('Quartz', 'SiO2', 'One of the most common minerals on Earth, quartz is a hard, crystalline mineral composed of silicon and oxygen. It occurs in many varieties including clear crystal, amethyst, and rose quartz.', 'Vitreous (glassy)', 7.0, 'Colorless, white, pink, purple, yellow', 'White', 'None', 'Conchoidal', 'Hexagonal', 2.65, 'Glass making, electronics, jewelry, abrasives', ARRAY['Worldwide', 'India - Rajasthan, Odisha']),
('Feldspar', 'KAlSi3O8 - NaAlSi3O8 - CaAl2Si2O8', 'A group of rock-forming minerals that make up about 60% of the Earth''s crust. Includes orthoclase, plagioclase, and microcline varieties.', 'Vitreous to pearly', 6.0, 'White, pink, gray, green', 'White', 'Perfect in two directions at 90°', 'Uneven', 'Monoclinic/Triclinic', 2.56, 'Ceramics, glass, enamel', ARRAY['Worldwide', 'India - Rajasthan, Gujarat']),
('Mica', '(K,Na)(Al,Mg,Fe)2(Si,Al)4O10(OH)2', 'A group of sheet silicate minerals known for their perfect basal cleavage and ability to split into thin, flexible sheets.', 'Vitreous to pearly', 2.5, 'Colorless, brown, green, black', 'White', 'Perfect basal cleavage', 'Uneven', 'Monoclinic', 2.8, 'Electrical insulation, cosmetics, paint', ARRAY['India - Jharkhand, Rajasthan', 'Brazil', 'Canada']),
('Calcite', 'CaCO3', 'A carbonate mineral and the most stable polymorph of calcium carbonate. It is a common constituent of sedimentary rocks.', 'Vitreous to pearly', 3.0, 'Colorless, white, yellow, pink', 'White', 'Perfect rhombohedral', 'Conchoidal', 'Hexagonal', 2.71, 'Cement, lime production, optical instruments', ARRAY['Worldwide', 'India - Rajasthan, Gujarat']),
('Hematite', 'Fe2O3', 'An important iron ore mineral with a characteristic red-brown streak. It is the mineral form of iron(III) oxide.', 'Metallic to dull', 6.0, 'Black, gray, red', 'Red to red-brown', 'None', 'Uneven to conchoidal', 'Hexagonal', 5.26, 'Iron ore, pigments, jewelry', ARRAY['India - Odisha, Jharkhand', 'Brazil', 'Australia']),
('Gypsum', 'CaSO4·2H2O', 'A soft sulfate mineral composed of calcium sulfate dihydrate. It forms as an evaporite mineral.', 'Vitreous to silky', 2.0, 'Colorless, white, gray', 'White', 'Perfect in one direction', 'Conchoidal', 'Monoclinic', 2.32, 'Plaster, drywall, cement', ARRAY['India - Rajasthan', 'USA', 'Spain']);
INSERT INTO public.geological_sites (name, description, country, state, district, latitude, longitude, rock_types, geological_formation, age, significance, accessibility, best_visit_time) VALUES
('Dhauli Hills', 'Famous for ancient rock edicts of Emperor Ashoka and distinctive white sedimentary rock formations. Site of the historic Kalinga War.', 'India', 'Odisha', 'Khorda', 20.2389, 85.7780, ARRAY['Sedimentary', 'Khondalite'], 'Part of Eastern Ghats Mobile Belt', 'Precambrian to Mesozoic', 'Historical and geological significance, contains ancient rock edicts', 'Easy access, 8 km from Bhubaneswar', 'October to March'),
('Bhitarkanika Mangroves', 'Unique geological setting where mangrove forests meet estuarine deposits, showcasing active sedimentation processes.', 'India', 'Odisha', 'Kendrapara', 20.7500, 87.0500, ARRAY['Recent alluvium', 'Estuarine deposits'], 'Modern deltaic formation', 'Quaternary (Recent)', 'Active sedimentation zone, biodiversity hotspot', 'Requires boat access, moderate difficulty', 'November to February'),
('Gopalpur Beach', 'Coastal area with exposed Precambrian rocks, beach deposits, and evidence of coastal erosion processes.', 'India', 'Odisha', 'Ganjam', 19.2667, 85.0000, ARRAY['Khondalite', 'Charnockite'], 'Eastern Ghats Mobile Belt', 'Precambrian', 'Study of coastal geomorphology and ancient crustal rocks', 'Easy access', 'October to March'),
('Khandadhar Waterfall', 'One of India''s highest waterfalls, cutting through ancient banded iron formations rich in hematite and magnetite.', 'India', 'Odisha', 'Sundargarh', 22.0167, 85.2667, ARRAY['Banded Iron Formation', 'Granite'], 'Iron Ore Group', 'Precambrian', 'Major iron ore deposits, showcases BIF formations', 'Moderate to difficult access', 'October to March'),
('Satkosia Gorge', 'Deep gorge cut by Mahanadi River through granite hills, exposing ancient igneous rock formations.', 'India', 'Odisha', 'Angul', 20.6667, 84.7500, ARRAY['Granite', 'Gneiss'], 'Eastern Ghats Granulite Complex', 'Precambrian', 'River morphology through hard rock terrain, wildlife sanctuary', 'Moderate access, boat available', 'November to February'),
('Nandan Kanan', 'Area with varied geological features including laterite deposits, granite outcrops, and forest ecosystems.', 'India', 'Odisha', 'Khorda', 20.4000, 85.8167, ARRAY['Granite', 'Laterite'], 'Weathered Eastern Ghats rocks', 'Precambrian to Quaternary', 'Weathering profiles, laterite formation', 'Easy access, zoo and botanical garden', 'October to March');